        "url": "https://cdn.discordapp.com/attachments/1269536886586609695/1346014878871195658/dont_give_up.mp4?ex=6afff08a&is=6afe9f0a&hm=82ea3843cdf40153947711e5c27b24c9cd91a7f1e8f92f880b4dd186c79b5d14&",
        "originalUrl": "https://cdn.discordapp.com/attachments/1269536886586609695/1346014878871195658/dont_give_up.mp4?ex=6afff08a&is=6afe9f0a&hm=82ea3843cdf40153947711e5c27b24c9cd91a7f1e8f92f880b4dd186c79b5d14&",
